use std::fs; fn main() { let pid = std::process::id(); if let Ok(stat) = fs::read_to_string(format!("/proc/{}/stat", pid)) { let parts: Vec<&str> = stat.split_whitespace().collect(); if parts.len() > 20 { let utime: u64 = parts[13].parse().unwrap_or(0); let stime: u64 = parts[14].parse().unwrap_or(0); let num_threads: u32 = parts[19].parse().unwrap_or(0); println!("utime: {}, stime: {}, threads: {}", utime, stime, num_threads); } } if let Ok(io) = fs::read_to_string(format!("/proc/{}/io", pid)) { for line in io.lines() { if line.starts_with("read_bytes:") { let bytes: u64 = line.trim_start_matches("read_bytes:").trim().parse().unwrap_or(0); println!("read_bytes: {}", bytes); } else if line.starts_with("write_bytes:") { let bytes: u64 = line.trim_start_matches("write_bytes:").trim().parse().unwrap_or(0); println!("write_bytes: {}", bytes); } } } }
